    guid_start = source.index('static const GUID NetModemServiceGuid =')
    guid_end = source.index('\n\n/*', guid_start)
    provider_guids = source[guid_start:guid_end]
    prefix = '\n#include <algorithm>\n#include <cassert>\n#include <cstdint>\n#include <cstdlib>\n#include <cstring>\n#include <iostream>\n#include <new>\n#include <string>\n#include <vector>\nusing DWORD = std::uint32_t;\nusing WORD = std::uint16_t;\nusing HRESULT = int;\nusing LONG = std::int32_t;\nusing HPSTR = char *;\nusing HANDLE = std::uintptr_t;\nusing size_t = std::size_t;\nstatic const int DP_OK = 0;\nstatic const DWORD DPOPEN_CREATE = 2;\nstatic const DWORD DPSESSION_MIGRATEHOST = 4;\nstatic const DWORD DPSESSION_JOINDISABLED = 0x20;\nstatic const int MB_OK = 0;\n\nstruct GUID {\n  DWORD Data1;\n  WORD Data2;\n  WORD Data3;\n  unsigned char Data4[8];\n};\nstruct DPCAPS { DWORD dwSize; unsigned char rest[0x24]; };\nstruct DPSESSIONDESC2 {\n  DWORD dwSize, dwFlags;\n  GUID guidInstance, guidApplication;\n  DWORD dwMaxPlayers, dwCurrentPlayers;\n  char *lpszSessionNameA, *lpszPasswordA;\n  DWORD dwReserved1, dwReserved2, dwUser1, dwUser2, dwUser3, dwUser4;\n};\nstruct Heap;\nstruct Net;\nstruct IDirectPlay2 {\n  DWORD incoming_from = 0, incoming_to = 0;\n  DWORD send_from = 0, send_to = 0, send_flags = 0, send_size = 0;\n  WORD sent_type = 0;\n  int sends = 0, closes = 0, receives = 0;\n  bool ready = false;\n  std::vector<unsigned char> incoming;\n  DPSESSIONDESC2 opened{}, live{};\n  int Open(DPSESSIONDESC2 *desc, DWORD) { opened = *desc; live = *desc; return DP_OK; }\n  int Close() { ++closes; return DP_OK; }\n  int GetCaps(DPCAPS *caps, DWORD) { return caps->dwSize == 0x28 ? DP_OK : 1; }\n  int GetSessionDesc(void *desc, unsigned long *size) {\n    if (desc == 0) { *size = sizeof(live); return DP_OK; }\n    *static_cast<DPSESSIONDESC2 *>(desc) = live;\n    *size = sizeof(live);\n    return DP_OK;\n  }\n  int Receive(DWORD *from, DWORD *to, DWORD, void *buffer, DWORD *size) {\n    ++receives;\n    if (!ready) return 1;\n    *from = incoming_from;\n    *to = incoming_to;\n    assert(incoming.size() <= *size);\n    std::memcpy(buffer, incoming.data(), incoming.size());\n    *size = static_cast<DWORD>(incoming.size());\n    ready = false;\n    return DP_OK;\n  }\n  int Send(DWORD from, DWORD to, DWORD flags, void *data, DWORD size) {\n    send_from = from; send_to = to; send_flags = flags; send_size = size;\n    std::memcpy(&sent_type, data, sizeof(sent_type));\n    ++sends;\n    return DP_OK;\n  }\n};\nIDirectPlay2 *NetDirectPlay = 0;\nDPCAPS NetServiceCaps{};\nHeap *StringAllocationHeap = 0;\nstd::vector<std::size_t> mem_get_sizes;\nvoid *mem_get(int size) {\n  mem_get_sizes.push_back(static_cast<std::size_t>(size));\n  return std::malloc(static_cast<std::size_t>(size));\n}\nint MessageBoxA(void *, const char *, const char *, int) { return 0; }\n\nstruct Heap {\n  std::string name;\n  std::vector<std::size_t> requests;\n  explicit Heap(const char *n) : name(n) {}\n  void *get(std::size_t size) {\n    requests.push_back(size);\n    return std::malloc(size);\n  }\n};\nstruct StringAllocationBase {\n  Heap *allocation_owner_;\n  StringAllocationBase() : allocation_owner_(StringAllocationHeap) {\n    StringAllocationHeap = 0;\n  }\n};\nstruct VoiceRxAllocation : StringAllocationBase {\n  int init_calls = 0;\n  int init_result = 0;\n  int buffers = 0;\n  int playing = 0;\n  int started = 0;\n  int stopped = 0;\n  int init(unsigned long, void *, unsigned long) { ++init_calls; return init_result; }\n  int get_nbuffers() { return buffers; }\n  int add_buffer(void *) { return 0; }\n  int is_playing() { return playing; }\n  int start() { ++started; return 0; }\n  int stop() { ++stopped; return 0; }\n};\nstruct VoiceReceiverEntry : StringAllocationBase {\n  int id_ = 0;\n  VoiceRxAllocation *payload_ = 0;\n  VoiceReceiverEntry *next_ = 0;\n  VoiceReceiverEntry *previous_ = 0;\n};\nstruct JackalVoiceRx : StringAllocationBase {\n  VoiceReceiverEntry *head_ = 0, *cursor_ = 0;\n  int count_ = 0, cursor_index_ = 0;\n  Heap *entries_heap_ = 0;\n  int insert_calls = 0;\n  int on_insert(void *) { ++insert_calls; return 0; }\n  int add_player(int player_id);\n};\nstruct NetPlayer {\n  DWORD field_0_ = 0, field_4_ = 0, field_8_ = 0, field_C_ = 0, stamp_10_ = 0;\n  unsigned char flags_14_ = 0;\n  char name_and_tail_[0x43]{};\n};\nstruct NetAllocationNode {\n  char *session_name_ = 0, *password_ = 0;\n  GUID instance_guid_{};\n  DWORD session_flags_ = 0, max_players_ = 0, current_players_ = 0, field_28_ = 0;\n};\nstruct NetFifo {\n  int count_ = 0, calls = 0;\n  DWORD last_size = 0, last_from = 0;\n  unsigned long last_stamp = 0;\n  std::vector<unsigned char> payload;\n  int add(const void *data, DWORD size, DWORD from, int, unsigned long stamp) {\n    ++calls; ++count_; last_size = size; last_from = from; last_stamp = stamp;\n    payload.resize(size);\n    if (size != 0) std::memcpy(payload.data(), data, size);\n    return 0;\n  }\n};\nstruct Net {\n  DWORD field_44_ = 0, voice_flags_D8_ = 0, field_E4_ = 1;\n  DWORD field_6D4_ = 0;\n  DWORD field_6D8_ = 0xC8, field_6DC_ = 0, field_6E4_ = 0x2000;\n  DWORD field_760_ = 0, field_764_ = 0;\n  unsigned char field_6EC_[16]{};\n  GUID *guid_6E8_ = 0;\n  NetAllocationNode allocation_node_{};\n  NetPlayer players_[16]{};\n  NetFifo queue_10c_{}, queue_130_{};\n  JackalVoiceRx jackal_voice_rx_{};\n  int added_calls = 0, helper_calls = 0;\n  std::string added_name;\n  DWORD added_id = 0;\n  NetAllocationNode *create_session(char *, int, char *);\n  int sub_632cc0(char *, int, unsigned char);\n  void broadcast_player_table() { ++helper_calls; }\n  void on_player_added(char *name, unsigned long id) {\n    ++added_calls; added_name = name; added_id = static_cast<DWORD>(id);\n  }\n};\nvoid sub_62d5f0(Net *net, void *) { ++net->helper_calls; }\nstruct NetThreadInfo {\n  DWORD thread_id_ = 0;\n  HANDLE events_[5]{};\n  IDirectPlay2 *direct_play_ = 0;\n  Net *owner_ = 0;\n  void *buffer_ = 0;\n  DWORD lock_initialized_ = 0;\n  unsigned char receive_lock_[0x18]{};\n  int internal_receive();\n};\nstruct NetPacketEnvelope { WORD type_flags_, field_2_; DWORD sequence_4_; };\nstatic_assert(sizeof(NetPacketEnvelope) == 8, "wire envelope size");\nstruct MMIOINFO {\n  unsigned char prefix[0x14];\n  LONG cchBuffer;\n  HPSTR pchBuffer, pchNext, pchEndRead;\n  unsigned char suffix[0x24];\n};\nstd::vector<HANDLE> signaled_events;\nstd::vector<DWORD> posted_threads;\nint SetEvent(HANDLE h) { signaled_events.push_back(h); return 1; }\nint PostThreadMessageA(DWORD tid, unsigned int, std::uintptr_t, std::uintptr_t) {\n  posted_threads.push_back(tid); return 1;\n}\nDWORD timeGetTime() { return 1234; }\nint get_sound_version() { return 0; }\n'
    tests = '\nvoid player_controls() {\n  Net net;\n  net.field_760_ = 8; net.field_764_ = 9;\n  net.players_[0].field_0_ = 11;\n  net.players_[1].field_0_ = 22;\n  const int duplicate = net.sub_632cc0(const_cast<char *>("ignored"), 11, 1);\n  assert(duplicate == 11 && net.field_6DC_ == 0 && net.added_calls == 0);\n  assert(net.jackal_voice_rx_.count_ == 0 && net.field_764_ == 9);\n\n  const int added = net.sub_632cc0(const_cast<char *>("fresh"), 33, 0);\n  assert(added == 0 && net.players_[2].field_0_ == 33);\n  assert(std::strcmp(net.players_[2].name_and_tail_, "fresh") == 0);\n  assert(net.field_6DC_ == 1 && net.added_calls == 1);\n  assert(net.added_name == "fresh" && net.added_id == 33);\n  assert(net.jackal_voice_rx_.count_ == 1);\n  assert(net.jackal_voice_rx_.head_->payload_->init_calls == 1);\n\n  // Full-table overlapping-member reads are checked against the pin, not executed.\n\n}\n\nvoid allocator_controls() {\n  Heap explicit_heap("explicit"), inherited("inherited");\n  JackalVoiceRx list;\n  list.entries_heap_ = &explicit_heap;\n  list.allocation_owner_ = &inherited;\n  assert(list.add_player(1) == 0);\n  assert((explicit_heap.requests ==\n          std::vector<std::size_t>{sizeof(VoiceReceiverEntry), sizeof(VoiceRxAllocation)}));\n  assert(inherited.requests.empty());\n  assert(list.head_->allocation_owner_ == &explicit_heap);\n  assert(list.head_->payload_->allocation_owner_ == &explicit_heap);\n\n  assert(list.add_player(2) == 0);\n  assert((inherited.requests ==\n          std::vector<std::size_t>{sizeof(VoiceReceiverEntry)}));\n  assert((explicit_heap.requests == std::vector<std::size_t>{\n      sizeof(VoiceReceiverEntry), sizeof(VoiceRxAllocation), sizeof(VoiceRxAllocation)}));\n  assert(list.head_->previous_->allocation_owner_ == &inherited);\n  assert(list.head_->previous_->payload_->allocation_owner_ == &explicit_heap);\n\n  Heap fallback_heap("fallback");\n  JackalVoiceRx fallback;\n  fallback.allocation_owner_ = &fallback_heap;\n  assert(fallback.add_player(3) == 0 && fallback.add_player(4) == 0);\n  assert((fallback_heap.requests ==\n          std::vector<std::size_t>{sizeof(VoiceReceiverEntry), sizeof(VoiceRxAllocation),\n                                   sizeof(VoiceReceiverEntry), sizeof(VoiceRxAllocation)}));\n}\n\nvoid receive_controls() {\n  Net net;\n  IDirectPlay2 dp;\n  unsigned char buffer[0x2000]{};\n  NetThreadInfo info;\n  info.direct_play_ = &dp; info.owner_ = &net; info.buffer_ = buffer;\n  info.thread_id_ = 77;\n  for (int i = 0; i != 5; ++i) info.events_[i] = static_cast<HANDLE>(10 + i);\n  net.field_760_ = 0x1234;\n\n  auto packet = [&](WORD type, DWORD from) {\n    dp.incoming.assign(20, 0);\n    std::memcpy(dp.incoming.data(), &type, sizeof(type));\n    dp.incoming_from = from; dp.incoming_to = 0x8888; dp.ready = true;\n  };\n\n  NetDirectPlay = 0;\n  packet(0, 0);\n  assert(info.internal_receive() == 0 && dp.receives == 0);\n  NetDirectPlay = &dp;\n\n  packet(0, 0);\n  assert(info.internal_receive() == 1);\n  assert(net.queue_130_.calls == 1 && net.queue_130_.last_size == 20);\n  assert(posted_threads.back() == 77 && signaled_events.back() == info.events_[1]);\n\n  packet(1, 42);\n  assert(info.internal_receive() == 1);\n  assert(net.queue_10c_.calls == 1 && net.queue_10c_.last_size == 8);\n  assert(net.queue_10c_.last_from == 42 && signaled_events.back() == info.events_[4]);\n\n  packet(0x10, 43);\n  assert(info.internal_receive() == 1);\n  assert(net.queue_130_.calls == 2 && net.queue_130_.last_size == 20);\n  assert(posted_threads.back() == 77 && signaled_events.back() == info.events_[1]);\n\n  packet(4, 44);\n  const DWORD sequence = 1;\n  std::memcpy(dp.incoming.data() + 4, &sequence, sizeof(sequence));\n  assert(info.internal_receive() == 1);\n  assert(net.queue_10c_.calls == 2 && net.queue_10c_.last_size == 8);\n  assert(dp.sends == 1 && dp.send_from == net.field_760_ && dp.send_to == 0x8888);\n  assert(dp.send_flags == 0 && dp.send_size == 0x0c && dp.sent_type == 2);\n  assert(signaled_events.back() == info.events_[4]);\n\n  net.players_[0].field_0_ = 46;\n  net.players_[0].field_8_ = 1;\n  net.field_E4_ = 2;\n  packet(2, 46);\n  const DWORD completion_sequence = 2;\n  std::memcpy(dp.incoming.data() + 4, &completion_sequence, sizeof(completion_sequence));\n  assert(info.internal_receive() == 1);\n  assert(net.players_[0].field_8_ == 0 && signaled_events.back() == info.events_[0]);\n\n  net.queue_10c_.count_ = 0xC8;\n  const int calls = net.queue_10c_.calls;\n  const std::size_t signals = signaled_events.size();\n  packet(1, 45);\n  assert(info.internal_receive() == 1);\n  assert(net.queue_10c_.calls == calls && signaled_events.size() == signals);\n}\n\nvoid create_session_version_control() {\n  GUID app{0x11111111, 0x2222, 0x3333, {1,2,3,4,5,6,7,8}};\n  Net net;\n  net.guid_6E8_ = &app;\n  net.field_44_ = 0xA1B2C3D4;\n  IDirectPlay2 dp;\n  NetDirectPlay = &dp;\n  NetAllocationNode *created = net.create_session(\n      const_cast<char *>("session"), 7, const_cast<char *>("secret"));\n  assert(created == &net.allocation_node_);\n  assert(dp.opened.dwUser1 == 0xA1B2C3D4);\n  assert(dp.opened.dwUser2 == 0);\n  assert(dp.opened.dwFlags == DPSESSION_MIGRATEHOST);\n  assert(dp.opened.dwMaxPlayers == 7);\n  assert(net.voice_flags_D8_ & 0x10000);\n  assert(std::strcmp(net.allocation_node_.session_name_, "session") == 0);\n  assert(std::strcmp(net.allocation_node_.password_, "secret") == 0);\n}\n\nint main() {\n  player_controls();\n  allocator_controls();\n  receive_controls();\n  create_session_version_control();\n  std::cout << "PASS: extracted v5 C++ bodies: player, allocator, receive, create_session\\n";\n}\n'
    prefix = prefix.replace(
        '  GUID *guid_6E8_ = 0;',
        '  GUID *guid_6E8_ = 0; GUID service_provider_guid_{};',
        1,
    )
    tests = tests.replace(
        '  assert(std::strcmp(net.allocation_node_.password_, "secret") == 0);',
        '  assert(std::strcmp(net.allocation_node_.password_, "secret") == 0);\n'
        '  assert(dp.opened.guidApplication.Data1 == app.Data1);\n'
        '  Net modem; IDirectPlay2 modem_dp; modem.guid_6E8_ = &app;\n'
        '  modem.service_provider_guid_ = NetModemServiceGuid; NetDirectPlay = &modem_dp;\n'
        '  assert(modem.create_session(const_cast<char *>("m"), 9, 0) == &modem.allocation_node_);\n'
        '  assert(modem_dp.opened.dwMaxPlayers == 2);\n'
        '  Net serial; IDirectPlay2 serial_dp; serial.guid_6E8_ = &app;\n'
        '  serial.service_provider_guid_ = NetSerialServiceGuid; NetDirectPlay = &serial_dp;\n'
        '  assert(serial.create_session(const_cast<char *>("s"), 9, 0) == &serial.allocation_node_);\n'
        '  assert(serial_dp.opened.dwMaxPlayers == 2);',
        1,
    )
    program = prefix + '\n' + provider_guids + '\n'
    program += allocator + '\n' + voice_add + '\n' + player_add + '\n'
    program += receive + '\n' + create_session + '\n' + tests
    with tempfile.TemporaryDirectory(prefix='net-v3-host-control-') as temp:
        binary = str(Path(temp) / 'control')
        built = subprocess.run(['g++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-x', 'c++', '-', '-o', binary], input=program, text=True, capture_output=True, timeout=30)
        if built.returncode:
            raise SystemExit(built.stderr)
        result = subprocess.run([binary], text=True, capture_output=True, timeout=30)
        if result.returncode:
            raise SystemExit(result.stderr or f'host control exited {result.returncode}')
        print(result.stdout, end='')

